import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { releasePackagesForPlan } from './release-packages.mjs';

const defaultRoot = resolve(import.meta.dirname, '..');

/**
 * Validates `.changeset/release-plan.json` when one is present. The plan is
 * generated by `npm run version-packages` inside the release pull request and
 * consumed by the publisher after merge, so a malformed plan must fail the
 * pull request rather than the publish.
 */
export async function checkReleasePlan({
  root = defaultRoot,
  writeStdout = (text) => process.stdout.write(text),
} = {}) {
  const planPath = resolve(root, '.changeset', 'release-plan.json');
  let plan;
  try {
    plan = JSON.parse(await readFile(planPath, 'utf8'));
  } catch (error) {
    if (error?.code === 'ENOENT') {
      writeStdout('No release plan is present; nothing to check.\n');
      return null;
    }
    throw error;
  }

  const selected = releasePackagesForPlan(plan);
  const versions = new Map();
  for (const entry of selected) {
    const manifest = JSON.parse(
      await readFile(
        resolve(root, 'packages', entry.directory, 'package.json'),
        'utf8',
      ),
    );
    versions.set(entry.name, manifest.version);
  }
  for (const planned of plan.packages) {
    const version = versions.get(planned.name);
    if (version !== planned.version) {
      throw new Error(
        `${planned.name} is ${version}, but the release plan requires ${planned.version}.`,
      );
    }
  }
  writeStdout(
    `Release plan: ${plan.packages
      .map(({ name, version }) => `${name}@${version}`)
      .join(', ')}.\n`,
  );
  return { packageCount: selected.length };
}

const invokedPath = process.argv[1] ? resolve(process.argv[1]) : null;
if (invokedPath === fileURLToPath(import.meta.url)) {
  await checkReleasePlan();
}
